const contracts = $input.all().map(i => i.json.fields);
const today = new Date();
const urgent = [];
const upcoming = [];
contracts.forEach(c => {
  const renewal = new Date(c['Renewal Date']);
  const daysLeft = Math.ceil((renewal - today) / (1000*60*60*24));
  const entry = { ...c, days_left: daysLeft };
  if (daysLeft <= 7) urgent.push(entry);
  else if (daysLeft <= 30) upcoming.push(entry);
});
return [{ json: { urgent, upcoming, total_active: contracts.length } }];

